        return `<li>${this._equipIcon(e)} ${sysTag} <b>${e.name}</b>${tTag} <span class="bag-stat">${stat(e)}</span>${treInfo(e)} ${btn}${inside ? '<span class="bag-active-now">当前生效</span>' : ''}</li>`;
